def livestock_name(sid, lang="zh"):
    e = LIVESTOCK.get(sid)
    if not e: return f'?{sid}'
    return e[0] if lang == 'zh' else e[1]

def creature_name(cid, lang="zh"):
    e = CREATURES.get(cid)
    if not e: return f'?{cid}'
    return e[0] if lang == 'zh' else e[1]
